mapper.select:
SELECT id, user_id as userId, title, content, emotion, place, time, interpretation, analysis_status as analysisStatus, analysis_error as analysisError, image_url as imageUrl, created_at as createdAt
FROM dream_content
WHERE id = #{id}

mapper.sql:
WHERE user_id = #{userId}

    AND (
        title LIKE CONCAT('%', #{keyword}, '%')
        OR content LIKE CONCAT('%', #{keyword}, '%')
        OR place LIKE CONCAT('%', #{keyword}, '%')
    )


    AND emotion = #{emotion}


    AND (
        (analysis_status IS NOT NULL AND analysis_status != '' AND analysis_status NOT IN ('PENDING', 'SUCCESS'))
        OR ((analysis_status IS NULL OR analysis_status = '') AND (interpretation IS NULL OR interpretation = ''))
    )

mapper.update:
UPDATE dream_content
SET title = #{title}
WHERE id = #{id}

UPDATE dream_content
SET interpretation = #{interpretation}
WHERE id = #{id}

UPDATE dream_content
SET analysis_status = #{status}, analysis_error = #{error}
WHERE id = #{id}
